package com.braseiro.dnd5e;
import org.json.JSONArray;import org.json.JSONObject;
/** Persistent political timeline: offices, control changes, decrees and scheduled expiry. */
public final class PoliticalChangeEngine{
 private PoliticalChangeEngine(){}
 public static JSONObject apply(JSONObject state,JSONObject event,int day){JSONObject o=copy(state);try{if(event==null)return o;String region=event.optString("region").trim();if(region.length()==0)return o;JSONObject regions=obj(o,"regions"),r=obj(regions,region);String ruler=event.optString("ruler").trim(),faction=event.optString("controlling_faction").trim();if(ruler.length()>0)r.put("ruler",ruler);if(faction.length()>0)r.put("controlling_faction",faction);r.put("last_change_day",Math.max(1,day));regions.put(region,r);o.put("regions",regions);String decree=event.optString("decree").trim();if(decree.length()>0)add(o,"decrees",new JSONObject().put("key",event.optString("key",region+":"+day+":"+decree)).put("region",region).put("text",decree).put("start_day",day).put("expires_day",event.optInt("expires_day",Integer.MAX_VALUE)).put("status","active"));add(o,"timeline",new JSONObject().put("day",day).put("region",region).put("kind",event.optString("kind","political_change")).put("summary",event.optString("summary")));}catch(Exception ignored){}return o;}
 public static JSONObject advanceDay(JSONObject state,int day){JSONObject o=copy(state);try{JSONArray a=arr(o,"decrees");for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d==null)continue;if("active".equals(d.optString("status"))&&d.optInt("expires_day",Integer.MAX_VALUE)<=day){d.put("status","expired").put("expired_day",Math.max(1,day)).put("consequence_pending",true);add(o,"timeline",new JSONObject().put("key","decree_expired:"+d.optString("key")).put("day",Math.max(1,day)).put("region",d.optString("region")).put("kind","decree_expired").put("summary",d.optString("text")));}}o.put("decrees",a).put("current_day",Math.max(1,day));}catch(Exception ignored){}return o;}
 public static JSONObject acknowledgeDecreeExpiry(JSONObject state,String key,int day){JSONObject o=copy(state);try{JSONArray a=arr(o,"decrees");for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d!=null&&key.equals(d.optString("key")))d.put("consequence_pending",false).put("reviewed_day",Math.max(1,day));}o.put("decrees",a);}catch(Exception ignored){}return o;}
 public static JSONArray dueExpirations(JSONObject state,int day){JSONArray z=new JSONArray(),a=arr(state,"decrees");for(int i=0;i<a.length();i++){JSONObject d=a.optJSONObject(i);if(d!=null&&"active".equals(d.optString("status","active"))&&d.optInt("expires_day",Integer.MAX_VALUE)<=day)z.put(d);}return z;}
 private static void add(JSONObject o,String k,JSONObject v)throws Exception{JSONArray a=arr(o,k);String key=v.optString("key");if(key.length()>0)for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(x!=null&&key.equals(x.optString("key")))return;}a.put(v);o.put(k,a);}private static JSONObject copy(JSONObject o){try{return o==null?new JSONObject():new JSONObject(o.toString());}catch(Exception e){return new JSONObject();}}private static JSONObject obj(JSONObject o,String k){JSONObject x=o==null?null:o.optJSONObject(k);return x==null?new JSONObject():x;}private static JSONArray arr(JSONObject o,String k){JSONArray x=o==null?null:o.optJSONArray(k);return x==null?new JSONArray():x;}
}
